 return `<section class="integration-review-panel"><p class="eyebrow">REFERRAL EMAIL</p><h3>${esc(detail.subject||'Referral email')}</h3><p><b>From:</b> ${esc(detail.sender||'Unknown')}</p>${detail.body_text?`<div class="referral-message-body">${esc(detail.body_text)}</div>`:`<p>${esc(detail.snippet||'')}</p>`}${detail.attachments?.length?`<h4>Attachments</h4><ul>${detail.attachments.map(file=>`<li>${esc(file.filename||file.part_id)} · ${esc(file.mime_type||'file')} · ${Number(file.size_bytes||0).toLocaleString()} bytes</li>`).join('')}</ul>`:'<p class="muted">No attachments.</p>'}${detail.status==='new'?`<form id="referral-review-form" data-integration="${esc(detail.integration)}" data-entry="${esc(detail.id)}"><label>Link to patient<select name="patient_id">${integrationPatientOptions(detail.patient_id)}</select></label><label>Review note<textarea name="reason" required maxlength="500"></textarea></label><div class="actions"><button class="primary" name="action" value="link">Link referral</button><button name="action" value="dismiss">Dismiss</button></div></form>`:'<p class="notice">This referral has already been reviewed.</p>'}</section>`;
