let outboundState={provider:'ringcentral',integrations:[],items:[],detail:null};
const outboundProviderLabel=provider=>provider==='gmail'?'Gmail':'RingCentral';
const outboundCanReview=()=>['owner','clinician'].includes(me?.role)||['partner_admin','workflow_manager'].includes(me?.delegated_role);
const outboundSplit=value=>String(value||'').split(',').map(item=>item.trim()).filter(Boolean);
function outboundRow(item){return `<button class="integration-queue-row ${outboundState.detail?.id===item.id?'selected':''}" data-outbound-draft="${esc(item.id)}"><span class="integration-kind">${outboundState.provider==='gmail'?'EMAIL':esc(String(item.kind||'').toUpperCase())}</span><span><b>${esc(item.subject||human(item.kind||'communication'))}</b><small>${item.to?.length?esc(item.to.join(', ')):`Created ${esc(date(item.created_at))}`}</small></span><span class="status-badge ${esc(item.status)}">${esc(human(item.status))}</span></button>`;}
function ringCompose(integration){return `<form id="ringcentral-outbound-form" data-id="${esc(integration.id)}"><div class="form-grid"><label>Action<select name="kind" data-ringcentral-kind><option value="sms">Send SMS</option><option value="ringout">Start phone call</option><option value="fax">Send PDF fax</option></select></label><label>Recipient phone (E.164)<input name="recipient" required placeholder="+15551234567" pattern="\\+[0-9]{8,15}"></label></div><div data-ringcentral-sms><label>Practice SMS number (E.164)<input name="sender" placeholder="+15557654321"></label><label>Message<textarea name="text" maxlength="1000"></textarea></label></div><div data-ringcentral-fax hidden><label>PDF document<input name="document" type="file" accept="application/pdf"></label><label>Cover page note<textarea name="cover_page_text" maxlength="1024"></textarea></label></div><label class="review-ack"><input type="checkbox" name="recipient_reviewed" required> I reviewed the recipient. This creates a draft only.</label><button class="primary" type="submit">Create draft for review</button></form>`;}
function gmailCompose(integration){return `<form id="gmail-outbound-form" data-id="${esc(integration.id)}"><div class="form-grid"><label>To (comma separated)<input name="to" type="text" required placeholder="referrals@example.org"></label><label>Cc (optional)<input name="cc" type="text"></label></div><label>Subject<input name="subject" required maxlength="500"></label><label>Message<textarea name="body_text" required maxlength="65536"></textarea></label><label>Attachments (optional, 10 maximum)<input name="attachments" type="file" multiple></label><label class="review-ack"><input type="checkbox" name="recipient_reviewed" required> I reviewed the recipients. This creates a draft only.</label><button class="primary" type="submit">Create draft for review</button></form>`;}
function outboundDetail(){const value=outboundState.detail;if(!value)return '<section class="integration-empty"><h3>Select a draft</h3><p>Review its recipient and content before approving it.</p></section>';if(outboundState.provider==='ringcentral'){const draft=value.draft||{},payload=value.payload||{},canReview=outboundCanReview();return `<section class="integration-review-panel"><p class="eyebrow">REVIEWED ${esc(String(draft.kind||'COMMUNICATION').toUpperCase())}</p><h3>${esc(human(draft.status))}</h3><dl class="outbound-review-summary"><div><dt>Recipient</dt><dd>${esc(payload.recipient)}</dd></div>${payload.sender?`<div><dt>From</dt><dd>${esc(payload.sender)}</dd></div>`:''}${payload.filename?`<div><dt>Document</dt><dd>${esc(payload.filename)}</dd></div>`:''}</dl>${payload.text?`<pre>${esc(payload.text)}</pre>`:''}${payload.cover_page_text?`<p>${esc(payload.cover_page_text)}</p>`:''}${draft.last_error?`<div class="notice error"><b>Provider needs review</b><p>${esc(draft.last_error)}</p></div>`:''}${draft.status==='draft'&&canReview?`<form id="ringcentral-approve-form" data-id="${esc(draft.id)}"><label>Re-enter recipient to confirm<input name="confirmed_recipient" required value="${esc(payload.recipient)}"></label><label>Approval note<input name="reason" required maxlength="500"></label><button class="primary">Approve recipient and content</button></form>`:''}${draft.status==='approved'&&canReview?`<form id="ringcentral-send-form" data-id="${esc(draft.id)}"><div class="notice warning"><b>Separate send gate</b><p>This action contacts RingCentral. Provider acceptance does not prove delivery or call connection.</p></div><button class="primary">Send approved ${esc(human(draft.kind))}</button></form>`:''}${draft.status==='needs_review'&&canReview?`<form id="ringcentral-reconcile-form" data-id="${esc(draft.id)}"><div class="notice warning"><b>Verify before reconciling</b><p>Find the existing operation in RingCentral and enter its provider ID. Reconciliation verifies provider evidence and never retries the send.</p></div><label>RingCentral provider ID<input name="provider_id" required maxlength="240" autocomplete="off"></label><label>Evidence reviewed<input name="reason" required maxlength="500" placeholder="Where the provider record was verified"></label><button class="primary">Verify existing provider operation</button></form>`:''}${draft.status==='accepted'&&canReview?`<button data-ringcentral-refresh-outbound="${esc(draft.id)}">Refresh provider status</button>`:''}<details><summary>Audit history</summary>${(value.events||[]).map(event=>`<p><b>${esc(human(event.action))}</b> · ${esc(date(event.created_at))}</p>`).join('')||'<p>No events.</p>'}</details></section>`;}const item=value,canReview=outboundCanReview();return `<section class="integration-review-panel"><p class="eyebrow">REVIEWED EMAIL</p><h3>${esc(item.subject)}</h3><dl class="outbound-review-summary"><div><dt>To</dt><dd>${esc((item.to_addresses||[]).join(', '))}</dd></div>${item.cc_addresses?.length?`<div><dt>Cc</dt><dd>${esc(item.cc_addresses.join(', '))}</dd></div>`:''}<div><dt>Status</dt><dd>${esc(human(item.status))}</dd></div></dl><pre>${esc(item.body_text)}</pre>${item.attachments?.length?`<p>${item.attachments.length} reviewed attachment${item.attachments.length===1?'':'s'}</p>`:''}${item.last_error?`<div class="notice error"><b>Send needs review</b><p>${esc(item.last_error)}</p></div>`:''}${item.status==='draft'&&canReview?`<form id="gmail-outbound-action-form" data-id="${esc(item.id)}" data-version="${item.version}"><label>Approval note<input name="reason" required maxlength="500"></label><div class="actions"><button class="primary" name="action" value="approve">Approve content</button><button name="action" value="cancel">Cancel draft</button></div></form>`:''}${item.status==='approved'&&canReview?`<form id="gmail-outbound-action-form" data-id="${esc(item.id)}" data-version="${item.version}"><div class="notice warning"><b>Separate send gate</b><p>This action sends through the clinic-owned Gmail account.</p></div><label>Send note<input name="reason" required maxlength="500"></label><button class="primary" name="action" value="send">Send approved email</button></form>`:''}${item.status==='needs_review'&&canReview?`<form id="gmail-outbound-action-form" data-id="${esc(item.id)}" data-version="${item.version}"><div class="notice warning"><b>Verify in Sent mail</b><p>SunCharts searches Gmail for this draft's immutable Message-ID. Reconciliation verifies an existing sent message and never retries the send.</p></div><label>Evidence reviewed<input name="reason" required maxlength="500" placeholder="How Sent mail was verified"></label><button class="primary" name="action" value="reconcile">Verify existing sent message</button></form>`:''}${item.receipt?`<p class="notice"><b>Gmail accepted the message</b><br>${esc(item.receipt.gmail_message_id||'Provider receipt recorded')}</p>`:''}</section>`;}
function renderOutboundWorkspace(){const provider=outboundState.provider,integration=outboundState.integrations.find(item=>integrationProvider(item.provider)===provider),compose=integration?(provider==='gmail'?gmailCompose(integration):ringCompose(integration)):`<div class="notice"><b>${outboundProviderLabel(provider)} is not configured</b><p>Open Integrations to connect the clinic-owned account first.</p></div>`;$('tools').className='integration-operations';$('tools').innerHTML=`<header class="task-workspace-head"><div><p class="eyebrow">COMMUNICATIONS</p><h2>Send & review</h2><p>Create drafts, verify recipients, approve, then send through this EHR instance.</p></div><button data-refresh-outbound>Refresh</button></header><nav class="workspace-tabs" aria-label="Outbound communication providers"><button class="${provider==='ringcentral'?'active':''}" data-outbound-provider="ringcentral">Calls, SMS & fax</button><button class="${provider==='gmail'?'active':''}" data-outbound-provider="gmail">Email</button></nav><div class="notice warning"><b>Nothing sends automatically</b><p>Workflow and AI modules can prepare drafts, but a person must review and approve them. Sending is a separate action.</p></div><details class="ai-compose" ${outboundState.items.length?'':'open'}><summary>Create a ${esc(outboundProviderLabel(provider))} draft</summary>${compose}</details><div class="integration-queue-layout"><section class="integration-queue-list"><div class="section-head"><div><h3>Draft queue</h3><p>${outboundState.items.length} recent item${outboundState.items.length===1?'':'s'}</p></div></div>${outboundState.items.map(outboundRow).join('')||'<div class="integration-empty"><h3>No drafts yet</h3><p>Create a reviewed draft above or from Workflow Studio.</p></div>'}</section>${outboundDetail()}</div>`;}
async function showOutboundWorkspace(provider='ringcentral'){showTool('Send & review');$('tools').innerHTML='<p class="muted">Loading communication drafts…</p>';const registry=await integrationList();instanceIntegrationState={...instanceIntegrationState,items:registry.items||[]};const integration=(registry.items||[]).find(item=>integrationProvider(item.provider)===provider);let items=[];if(integration)items=(await api(provider==='gmail'?`/api/v1/integrations/${integration.id}/gmail/outbound-drafts`:`/api/v1/integrations/ringcentral/${integration.id}/outbound`).catch(()=>({items:[]}))).items||[];outboundState={provider,integrations:registry.items||[],items,detail:null};renderOutboundWorkspace();}
async function outboundFile(file){if(!file)return null;const bytes=new Uint8Array(await file.arrayBuffer()),parts=[];for(let index=0;index<bytes.length;index+=0x8000)parts.push(String.fromCharCode(...bytes.subarray(index,index+0x8000)));return btoa(parts.join(''));}

let aiReviewState={items:[],integrations:[],detail:null,selectedIntegrationId:null,connectionError:null,draftsError:null,formEdited:false};
let aiPrivacyReview=null,aiPrivacyRevision=0,aiPrivacyBusy=false;
function clearAiPrivacyReview(){aiPrivacyReview=null;aiPrivacyRevision++;aiPrivacyBusy=false;const host=$('ai-privacy-preview');if(host)host.innerHTML='';}
function aiPrivacyRequest(form){
 const values=Object.fromEntries(new FormData(form)),pathway=values.pathway_instance_id||null,step=values.step_key||null;
 if(Boolean(pathway)!==Boolean(step))throw new Error('Workflow instance and step are required together.');
 if(new TextEncoder().encode(values.source_text).length>65536)throw new Error('Source material must be 65,536 UTF-8 bytes or less.');
 return {integration_id:values.integration_id,purpose:values.purpose,instruction:values.instruction,source_text:values.source_text,pathway_instance_id:pathway,step_key:step};
}
async function aiPreparePrivacy(form){
 if(aiPrivacyBusy)return;clearAiPrivacyReview();const revision=aiPrivacyRevision,account=me,body=aiPrivacyRequest(form),operation={};aiPrivacyBusy=operation;
 try{
  const preview=await api('/api/v1/ai/privacy/preview','POST',body);
  if(account!==me||revision!==aiPrivacyRevision||$('ai-generate-form')!==form||JSON.stringify(aiPrivacyRequest(form))!==JSON.stringify(body))return;
  if(!sunPrivacyValid(preview))throw new Error('A valid privacy preview was not returned. Prepare it again before sending.');
  aiPrivacyReview={body,preview,form,account};aiReviewState.formEdited=true;
  $('ai-privacy-preview').innerHTML=`${sunPrivacyPreviewMarkup(preview)}<label class="review-ack"><input type="checkbox" name="privacy_approved"> I reviewed the exact outgoing instruction and source, including any remaining identifiers.</label><button type="button" class="primary" data-ai-privacy-execute>Approve preview and generate draft</button>`;
 }finally{if(aiPrivacyBusy===operation)aiPrivacyBusy=false;}
}
async function aiExecutePrivacy(){
 if(aiPrivacyBusy)return;const review=aiPrivacyReview;
 if(!review||review.account!==me||$('ai-generate-form')!==review.form||JSON.stringify(aiPrivacyRequest(review.form))!==JSON.stringify(review.body)||!sunPrivacyValid(review.preview)){clearAiPrivacyReview();throw new Error('The request changed or its preview expired. Prepare and review a new preview.');}
 if(!review.form.elements.privacy_approved?.checked)throw new Error('Review the outgoing instruction and source, then check the approval box.');
 const operation={},revision=aiPrivacyRevision;aiPrivacyBusy=operation;aiPrivacyReview=null;
 const current=()=>review.account===me&&revision===aiPrivacyRevision&&$('ai-generate-form')===review.form&&JSON.stringify(aiPrivacyRequest(review.form))===JSON.stringify(review.body);
 try{
  await api('/api/v1/ai/drafts','POST',{...review.body,request_id:crypto.randomUUID(),privacy_preview_id:review.preview.id,privacy_approved:true});if(!current())return;
  const [catalog,drafts]=await Promise.all([api('/api/v1/ai/connections').catch(error=>({items:[],error:error.message})),api('/api/v1/ai/drafts').catch(error=>({items:[],error:error.message}))]);
  if(!current())return;aiReviewState={...aiReviewState,items:drafts.items||[],integrations:catalog.items||[],detail:null,connectionError:catalog.error||null,draftsError:drafts.error||null};renderAiReview();notice('Sun draft received. Recognized placeholders were restored locally; review the result before use.');
 }finally{if(aiPrivacyBusy===operation){aiPrivacyBusy=false;if(current())clearAiPrivacyReview();}}
}
const aiDraftPurposes={structured_extraction:'Structured extraction',document_classification:'Document classification',draft_summary:'Draft summary',draft_response:'Draft administrative response'};
function aiAvailableConnections(){return aiReviewState.integrations.filter(item=>['claude','erebine'].includes(integrationProvider(item.provider))&&item.enabled);}
function aiSelectedConnection(){const items=aiAvailableConnections();return items.find(item=>item.id===aiReviewState.selectedIntegrationId)||items[0];}
function aiPurposeOptions(connection,selected){return Object.entries(aiDraftPurposes).filter(([key])=>(connection?.capabilities||[]).includes(key)).map(([key,label])=>`<option value="${key}" ${key===selected?'selected':''}>${esc(label)}</option>`).join('');}
function aiConnectionSummary(connection){return connection?`<b>${esc(aiProviderLabel(connection.provider))}</b> · ${esc(connection.model||'No model configured')}<br><small>The model is set in this EHR’s integration settings.</small>`:'';}
function aiDraftRow(item){return `<button class="integration-queue-row" data-ai-draft="${esc(item.id)}"><span class="integration-kind">${esc(aiProviderLabel(item.provider))}</span><span><b>${esc(human(item.purpose))}</b><small>${item.pathway_instance_id?`Workflow step · ${esc(item.step_key)}`:'Standalone reviewed draft'} · ${esc(item.model||'clinic model')}</small></span><span class="status-badge">${esc(human(item.status))}</span></button>`;}
function aiReviewDetail(){
 const detail=aiReviewState.detail;if(!detail)return '<section class="integration-empty"><h3>Select a draft to review</h3><p>AI output is never applied or sent automatically.</p></section>';
 const draft=detail.draft,connection=aiReviewState.integrations.find(item=>item.id===draft.integration_id);
 const privacy=draft.privacy,privacyNote=privacy?.status==='approved'?`<div class="notice"><b>Outgoing privacy preview approved</b><p>${Number(privacy.redaction_count||0)} identifier replacement${Number(privacy.redaction_count||0)===1?'':'s'} in the outgoing request. ${privacy.patient_context_used?'Known patient identifiers were used locally.':'No patient identity context was selected.'} ${draft.status==='failed'?'The request failed; no usable output was produced.':'Recognized response placeholders were restored locally.'}</p><p class="muted">${esc(privacy.limitations||'Identifier detection can miss details. Verify this draft against the local source.')} ${privacy.approved_at?`Reviewed ${esc(date(privacy.approved_at))}.`:''}</p></div>`:'<div class="notice warning"><b>No privacy preview recorded</b><p>This older draft does not have a recorded outgoing privacy review.</p></div>';
 return `<section class="integration-review-panel"><p class="eyebrow">HUMAN REVIEW REQUIRED</p><h3>${esc(human(draft.purpose))}</h3><div class="notice warning"><b>Draft only</b><p>Verify every statement against the source. Approval records review; it does not send a message or create a diagnosis.</p></div><dl class="outbound-review-summary"><div><dt>Provider</dt><dd>${esc(aiProviderLabel(draft.provider))}</dd></div><div><dt>Model used</dt><dd>${esc(draft.model||'Not recorded')}</dd></div>${connection?`<div><dt>Connection</dt><dd>${esc(connection.label)}</dd></div>`:''}${draft.created_at?`<div><dt>Requested</dt><dd>${esc(date(draft.created_at))}</dd></div>`:''}</dl>${privacyNote}${detail.local_input?`<details><summary>Local source and instruction</summary><p class="muted">Original text retained inside this EHR for review; this is not the provider payload.</p><h4>Instruction</h4><pre>${esc(detail.local_input.instruction||'')}</pre><h4>Source</h4><pre>${esc(detail.local_input.source_text||'')}</pre></details>`:''}${draft.pathway_instance_id?`<p><b>Workflow context:</b> ${esc(draft.step_key)} · instance ${esc(draft.pathway_instance_id)}</p>`:'<p class="muted">Standalone draft; no workflow step is linked.</p>'}<pre>${esc(draft.content||`Draft failed: ${draft.failure_code||'no content'}`)}</pre>${draft.status==='draft'&&(['owner','clinician'].includes(me.role)||me.delegated_role==='partner_admin')?`<form id="ai-review-form" data-id="${esc(draft.id)}" data-version="${draft.version}"><label>Review note<textarea name="reason" required maxlength="1000"></textarea></label><div class="actions"><button class="primary" name="action" value="approve">Approve reviewed draft</button><button name="action" value="reject">Reject draft</button></div></form>`:`<p class="notice">Status: ${esc(human(draft.status))}</p>`}</section>`;
}
function renderAiReview(){
 clearAiPrivacyReview();
 const connections=aiAvailableConnections(),selected=aiSelectedConnection();aiReviewState.selectedIntegrationId=selected?.id||null;
 $('tools').className='integration-operations';
 $('tools').innerHTML=`<header class="task-workspace-head"><div><p class="eyebrow">OPERATIONS</p><h2>Sun review</h2><p>Sun prepares drafts with this EHR’s enabled Claude or Erebine connection. Review every result before use.</p></div><button data-refresh-ai-review>Refresh</button></header><div class="notice warning"><b>Human review is mandatory</b><p>SunCharts treats AI output as untrusted draft material. Nothing is sent, charted or applied without a person’s explicit review.</p></div>${aiReviewState.connectionError?`<div class="notice error"><b>AI connections could not be loaded</b><p>${esc(aiReviewState.connectionError)}</p></div>`:''}<details class="ai-compose" ${aiReviewState.items.length?'':'open'}><summary>Prepare a reviewed draft</summary>${sunPrivacyPipeline()}${connections.length?`<form id="ai-generate-form"><label>AI connection<select name="integration_id" data-ai-connection required>${connections.map(item=>`<option value="${esc(item.id)}" ${item.id===selected.id?'selected':''}>${esc(aiProviderLabel(item.provider))} · ${esc(item.label)}</option>`).join('')}</select></label><p id="ai-connection-model" class="muted" aria-live="polite">${aiConnectionSummary(selected)}</p><label>Draft purpose<select name="purpose" required>${aiPurposeOptions(selected)}</select></label><label>Instruction<textarea name="instruction" required maxlength="4000" placeholder="Describe the reviewed output needed"></textarea></label><label>Source material<textarea name="source_text" required maxlength="65536" placeholder="Paste up to 65,536 UTF-8 bytes of source text to review"></textarea></label><div class="form-grid"><label>Workflow instance (optional)<input name="pathway_instance_id" placeholder="UUID"></label><label>Workflow step (optional)<input name="step_key" maxlength="63"></label></div><button class="primary" type="submit">Preview outgoing text</button><div id="ai-privacy-preview" aria-live="polite"></div></form>`:!aiReviewState.connectionError?`<p>No enabled Claude or Erebine connection is available for this EHR.</p>${integrationCanManage()?'<button data-open-integrations>Configure AI connections</button>':'<p class="muted">Ask your practice administrator to configure and enable an AI connection.</p>'}`:''}</details><div class="integration-queue-layout"><section class="integration-queue-list"><h3>Draft queue</h3>${aiReviewState.draftsError?`<div class="notice error"><b>Drafts could not be loaded</b><p>${esc(aiReviewState.draftsError)}</p></div>`:aiReviewState.items.map(aiDraftRow).join('')||'<div class="integration-empty"><p>No drafts yet.</p></div>'}</section>${aiReviewDetail()}</div>`;
 aiReviewState.formEdited=false;if(typeof flushSunRefreshHooks==='function')flushSunRefreshHooks();
}
async function showAiReviewWorkspace(){
 showTool('Sun review');$('tools').innerHTML='<p class="muted">Loading reviewed drafts…</p>';
 const [catalog,drafts]=await Promise.all([api('/api/v1/ai/connections').catch(error=>({items:[],error:error.message})),api('/api/v1/ai/drafts').catch(error=>({items:[],error:error.message}))]);
 aiReviewState={...aiReviewState,items:drafts.items||[],integrations:catalog.items||[],detail:null,connectionError:catalog.error||null,draftsError:drafts.error||null};renderAiReview();
}
async function openSunDraft(id){await showAiReviewWorkspace();aiReviewState.detail=await api(`/api/v1/ai/drafts/${encodeURIComponent(id)}`);renderAiReview();}
function aiReviewHasEdits(){return aiReviewState.formEdited||[...($('tools')?.querySelectorAll?.('#ai-generate-form textarea,#ai-generate-form input,#ai-review-form textarea')||[])].some(field=>String(field.value||'').length>0);}
async function refreshSunReview(changes=[],{isCurrent=()=>true}={}){
 const id=aiReviewState.detail?.draft?.id;
 const [catalog,drafts,detail]=await Promise.all([api('/api/v1/ai/connections'),api('/api/v1/ai/drafts'),id?api(`/api/v1/ai/drafts/${encodeURIComponent(id)}`):Promise.resolve(null)]);
 if(!isCurrent())return;
 aiReviewState={...aiReviewState,items:drafts.items||[],integrations:catalog.items||[],detail:id===aiReviewState.detail?.draft?.id?detail:aiReviewState.detail,connectionError:null,draftsError:null};renderAiReview();
}
if(typeof registerSunRefreshHook==='function')registerSunRefreshHook('sun-review',{topics:['ai','workflow'],active:()=>!!$('tools')?.querySelector?.('[data-refresh-ai-review]'),dirty:aiReviewHasEdits,refresh:refreshSunReview});

async function loadErebineModels(button){
 const id=button.dataset.erebineModels||null,form=button.form,values=Object.fromEntries(new FormData(form)),status=$('erebine-model-status');
 let result;
 if(id&&!values.secret){result=await api(`/api/v1/integrations/${id}/erebine/models`);}
 else{
  if(!values.secret||!values.project_id?.trim())throw new Error('Enter the Erebine API key and project ID to load models.');
  const config={project_id:values.project_id.trim()};for(const key of ['model','workspace_id','endpoint_slug'])if(values[key]?.trim())config[key]=values[key].trim();
  result=await api('/api/v1/integrations/erebine/models','POST',{config,credential:values.secret});
 }
 const models=(result.models||[]).filter(model=>aiModelId(model));if(id)erebineAvailableModels.set(id,models);
 if($('integration-settings-form')!==form)return;
 $('erebine-model-options').innerHTML=models.map(model=>`<option value="${esc(aiModelId(model))}">${esc(aiModelLabel(model))}</option>`).join('');
 if(status)status.textContent=models.length?`${models.length} model${models.length===1?'':'s'} available. Choose the exact model ID for this connection.`:'Erebine returned no available models for this connection. Check the project permissions and routing.';
}
async function testErebineConnection(id){
 const item=instanceIntegrationState.items.find(candidate=>candidate.id===id),result=await api(`/api/v1/integrations/${id}/erebine/models`),models=(result.models||[]).filter(model=>aiModelId(model));
 erebineAvailableModels.set(id,models);
 const configured=item?.config?.model,available=models.some(model=>aiModelId(model)===configured),message=available?'Erebine account access verified. The saved model is listed. Generate a reviewed draft to verify inference.':`Erebine responded, but the saved model is not listed. Review the model and routing settings before generating a draft.`;
 const status=$('erebine-test-status');if(status)status.textContent=message;notice(message,!available);
}
document.addEventListener('change',event=>{
 if(!event.target.matches?.('[data-ai-connection]'))return;
 aiReviewState.formEdited=true;aiReviewState.selectedIntegrationId=event.target.value;const connection=aiSelectedConnection(),form=event.target.form;
 $('ai-connection-model').innerHTML=aiConnectionSummary(connection);form.elements.purpose.innerHTML=aiPurposeOptions(connection,form.elements.purpose.value);
});
document.addEventListener('input',event=>{if(event.target.closest?.('#ai-generate-form,#ai-review-form'))aiReviewState.formEdited=true;if(event.target.closest?.('#ai-generate-form')&&event.target.name!=='privacy_approved')clearAiPrivacyReview();});
document.addEventListener('click',event=>{
 const button=event.target.closest?.('[data-erebine-models],[data-erebine-test]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();
 run(async()=>{if(button.hasAttribute('data-erebine-models'))await loadErebineModels(button);else await testErebineConnection(button.dataset.erebineTest);});
},true);

document.addEventListener('submit',event=>{
 const form=event.target;if(!['ringcentral-webhook-form','gmail-watch-form','communication-review-form','referral-review-form','ai-generate-form','ai-review-form','ringcentral-outbound-form','ringcentral-approve-form','ringcentral-send-form','ringcentral-reconcile-form','gmail-outbound-form','gmail-outbound-action-form'].includes(form.id))return;event.preventDefault();event.stopImmediatePropagation();
 run(async()=>{const data=new FormData(form),values=Object.fromEntries(data);if(form.id==='ringcentral-webhook-form'){await api(`/api/v1/integrations/ringcentral/${form.dataset.id}/subscription`,'POST',{transport:'webhook',public_base_url:values.public_base_url});notice('RingCentral webhook delivery configured.');return;}if(form.id==='gmail-watch-form'){const body={delivery_mode:values.delivery_mode,label_ids:values.label_ids.split(',').map(value=>value.trim()).filter(Boolean),poll_seconds:Number(values.poll_seconds)};if(values.delivery_mode==='pubsub')Object.assign(body,{topic_name:values.topic_name,public_base_url:values.public_base_url,oidc_audience:values.oidc_audience,oidc_service_account:values.oidc_service_account});await api(`/api/v1/integrations/${form.dataset.id}/gmail/watch`,'POST',body);await integrationAdapterPanel('gmail',integrationRecord('gmail'));notice(values.delivery_mode==='poll'?'Outbound Gmail polling configured.':'Gmail Pub/Sub push configured.');return;}if(form.id==='communication-review-form'){const action=event.submitter?.value||'review';await api(`/api/v1/integrations/ringcentral/${form.dataset.integration}/inbox/${form.dataset.event}`,'POST',{action,patient_id:values.patient_id||null,reason:values.reason});await showIntegrationInbox('communications');notice('Communication review recorded.');return;}if(form.id==='referral-review-form'){const action=event.submitter?.value||'link';await api(`/api/v1/integrations/${form.dataset.integration}/gmail/referrals/${form.dataset.entry}/actions`,'POST',{action,patient_id:action==='link'?(values.patient_id||null):null,reason:values.reason});await showIntegrationInbox('referrals');notice('Referral review recorded.');return;}if(form.id==='ringcentral-outbound-form'){const body={request_id:crypto.randomUUID(),kind:values.kind,recipient:values.recipient};if(values.kind==='sms')Object.assign(body,{sender:values.sender,text:values.text});if(values.kind==='ringout'&&values.sender)body.sender=values.sender;if(values.kind==='fax'){const file=form.elements.document.files[0];if(!file||file.type!=='application/pdf')throw new Error('Choose the reviewed PDF to fax.');Object.assign(body,{filename:file.name,content_type:'application/pdf',document_base64:await outboundFile(file),cover_page_text:values.cover_page_text||''});}await api(`/api/v1/integrations/ringcentral/${form.dataset.id}/outbound`,'POST',body);await showOutboundWorkspace('ringcentral');notice('RingCentral draft created. Review and approve it before sending.');return;}if(form.id==='ringcentral-approve-form'){const integration=outboundState.integrations.find(item=>integrationProvider(item.provider)==='ringcentral');await api(`/api/v1/integrations/ringcentral/${integration.id}/outbound/${form.dataset.id}/approve`,'POST',{request_id:crypto.randomUUID(),confirmed_recipient:values.confirmed_recipient,reason:values.reason});await showOutboundWorkspace('ringcentral');notice('Recipient and content approved. Sending remains a separate action.');return;}if(form.id==='ringcentral-send-form'){const integration=outboundState.integrations.find(item=>integrationProvider(item.provider)==='ringcentral');await api(`/api/v1/integrations/ringcentral/${integration.id}/outbound/${form.dataset.id}/send`,'POST',{request_id:crypto.randomUUID()});await showOutboundWorkspace('ringcentral');notice('RingCentral accepted the request. Delivery or call connection is not yet confirmed.');return;}if(form.id==='gmail-outbound-form'){const files=[...form.elements.attachments.files];if(files.length>10)throw new Error('Choose no more than 10 attachments.');const attachments=[];for(const file of files)attachments.push({filename:file.name,mime_type:file.type||'application/octet-stream',data_base64:await outboundFile(file)});await api(`/api/v1/integrations/${form.dataset.id}/gmail/outbound-drafts`,'POST',{idempotency_key:`browser-${crypto.randomUUID()}`,inbox_id:null,to:outboundSplit(values.to),cc:outboundSplit(values.cc),subject:values.subject,body_text:values.body_text,attachments});await showOutboundWorkspace('gmail');notice('Email draft created. Review and approve it before sending.');return;}if(form.id==='gmail-outbound-action-form'){const integration=outboundState.integrations.find(item=>integrationProvider(item.provider)==='gmail'),action=event.submitter?.value||'cancel';await api(`/api/v1/integrations/${integration.id}/gmail/outbound-drafts/${form.dataset.id}/actions`,'POST',{action,reason:values.reason,expected_version:Number(form.dataset.version)});await showOutboundWorkspace('gmail');notice(action==='send'?'Gmail accepted the approved message.':`Email draft ${action==='approve'?'approved':'cancelled'}.`);return;}if(form.id==='ai-generate-form'){await aiPreparePrivacy(form);return;}const action=event.submitter?.value||'reject';await api(`/api/v1/ai/drafts/${form.dataset.id}/actions`,'POST',{action,reason:values.reason},Number(form.dataset.version));await showAiReviewWorkspace();notice(`Draft ${action==='approve'?'approved':'rejected'}.`);});
},true);
document.addEventListener('click',event=>{
 const button=event.target.closest?.('[data-adapter-test],[data-ringcentral-subscribe],[data-gmail-sync],[data-open-integration-inbox],[data-inbox-tab],[data-communication-event],[data-referral-entry],[data-refresh-integration-inbox],[data-open-ai-review],[data-ai-draft],[data-refresh-ai-review],[data-open-integrations],[data-open-outbound],[data-outbound-provider],[data-outbound-draft],[data-refresh-outbound],[data-ringcentral-refresh-outbound]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();
 run(async()=>{if(button.hasAttribute('data-ai-privacy-execute')){await aiExecutePrivacy();return;}if(button.hasAttribute('data-open-integrations')){await showApps();return;}if(button.dataset.openOutbound){closeIntegrationEditor();await showOutboundWorkspace(button.dataset.openOutbound);return;}if(button.dataset.outboundProvider){await showOutboundWorkspace(button.dataset.outboundProvider);return;}if(button.hasAttribute('data-refresh-outbound')){await showOutboundWorkspace(outboundState.provider);return;}if(button.dataset.outboundDraft){const integration=outboundState.integrations.find(item=>integrationProvider(item.provider)===outboundState.provider);outboundState.detail=await api(outboundState.provider==='gmail'?`/api/v1/integrations/${integration.id}/gmail/outbound-drafts/${button.dataset.outboundDraft}`:`/api/v1/integrations/ringcentral/${integration.id}/outbound/${button.dataset.outboundDraft}`);renderOutboundWorkspace();return;}if(button.dataset.ringcentralRefreshOutbound){const integration=outboundState.integrations.find(item=>integrationProvider(item.provider)==='ringcentral');await api(`/api/v1/integrations/ringcentral/${integration.id}/outbound/${button.dataset.ringcentralRefreshOutbound}/refresh`,'POST',{});await showOutboundWorkspace('ringcentral');notice('RingCentral provider status refreshed.');return;}if(button.dataset.openIntegrationInbox){closeIntegrationEditor();await showIntegrationInbox(button.dataset.openIntegrationInbox);return;}if(button.hasAttribute('data-open-ai-review')){closeIntegrationEditor();await showAiReviewWorkspace();return;}if(button.dataset.adapterTest==='ringcentral'){await api(`/api/v1/integrations/ringcentral/${button.dataset.id}/test`,'POST',{});notice('RingCentral account verified.');return;}if(button.dataset.ringcentralSubscribe){await api(`/api/v1/integrations/ringcentral/${button.dataset.ringcentralSubscribe}/subscription`,'POST',{transport:'websocket'});notice('RingCentral outbound live feed is starting.');return;}if(button.dataset.gmailSync){const result=await api(`/api/v1/integrations/${button.dataset.gmailSync}/gmail/sync`,'POST',{});notice(`${result.processed||0} Gmail change${result.processed===1?'':'s'} processed.`);return;}if(button.dataset.inboxTab){integrationInboxState.tab=button.dataset.inboxTab;integrationInboxState.detail=null;renderIntegrationInbox();return;}if(button.hasAttribute('data-refresh-integration-inbox')){await showIntegrationInbox(integrationInboxState.tab);return;}if(button.dataset.communicationEvent){const item=integrationRecord('ringcentral'),result=await api(`/api/v1/integrations/ringcentral/${item.id}/inbox/${button.dataset.communicationEvent}`);integrationInboxState.detail={type:'communications',integration:item.id,...result};renderIntegrationInbox();return;}if(button.dataset.referralEntry){const item=integrationRecord('gmail'),result=await api(`/api/v1/integrations/${item.id}/gmail/referrals/${button.dataset.referralEntry}`);integrationInboxState.detail={type:'referrals',integration:item.id,...result};renderIntegrationInbox();return;}if(button.hasAttribute('data-refresh-ai-review')){await showAiReviewWorkspace();return;}if(button.dataset.aiDraft){aiReviewState.detail=await api(`/api/v1/ai/drafts/${button.dataset.aiDraft}`);renderAiReview();}});
},true);
document.addEventListener('change',event=>{if(!event.target.matches?.('[data-ringcentral-kind]'))return;const form=event.target.form,kind=event.target.value;form.querySelector('[data-ringcentral-sms]').hidden=!['sms','ringout'].includes(kind);form.querySelector('[data-ringcentral-fax]').hidden=kind!=='fax';form.elements.sender.required=kind==='sms';form.elements.text.required=kind==='sms';form.elements.document.required=kind==='fax';});
